}
function postText(array $x):string{return fb_post_text($x);}
function ensureListingAssets(array $x):array{
  $urls=$x['imageUrls']??[];$source=txt($x['sourceUrl']??'');$cache=photoCache();$key=sid($x['id']??'')?:hash('sha256',$source);$entry=is_array($cache[$key]??null)?$cache[$key]:[];$dirty=false;
  $cachedUrls=is_array($entry['urls']??null)?array_values(array_filter(array_map('txt',$entry['urls']))):[];
  $needsMeta=$source!==''&&(!$urls&&count($cachedUrls)<2||txt($x['city']??'')===''&&txt($entry['city']??'')===''||txt($x['district']??'')===''&&txt($entry['district']??'')===''||txt($entry['address']??'')==='');
