  if(txt($entry['address']??'')!==''&&$amenitiesStale){$geo=geocodeAddress(txt($entry['address']));$entry['amenitiesFetchedAt']=date('c');$entry['amenities']=[];if($geo){$entry=array_merge($entry,$geo);$entry['amenities']=fetchAmenities((float)$geo['lat'],(float)$geo['lon']);}$dirty=true;}
  if($dirty){$cache[$key]=$entry;writePhotoCache($cache);}
  if(!$urls&&$cachedUrls)$urls=$cachedUrls;if(!$urls&&txt($entry['url']??'')!=='')$urls=[txt($entry['url'])];
  if(txt($x['city']??'')===''&&txt($entry['city']??'')!=='')$x['city']=txt($entry['city']);if(txt($x['district']??'')===''&&txt($entry['district']??'')!=='')$x['district']=txt($entry['district']);
  $public=publicSiteItem(txt($x['id']??''));if(txt($x['layout']??'')===''&&txt($public['layout']??'')!=='')$x['layout']=txt($public['layout']);if(txt($x['type']??'')===''&&txt($public['category']??'')!=='')$x['type']=txt($public['category']);if(txt($x['summaryZh']??'')===''&&txt($public['summaryZh']??'')!=='')$x['summaryZh']=txt($public['summaryZh']);
  $x['imageUrls']=array_slice(array_values(array_unique($urls)),0,10);$x['businessCardUrl']='https://huowang.paohui.org/huowang/assets/huowang-card.jpg';$x['amenities']=is_array($entry['amenities']??null)?$entry['amenities']:[];$x['amenitiesAddress']=txt($entry['address']??'');
  $missing=listv($x['missingFields']??[]);if(txt($x['city']??'')!=='')$missing=array_values(array_diff($missing,['縣市']));if(txt($x['district']??'')!=='')$missing=array_values(array_diff($missing,['鄉鎮區']));if(!$x['imageUrls']&&!in_array('照片',$missing,true))$missing[]='照片';$x['missingFields']=$missing;$x['postText']=ensureBrokerDisclosure(postText($x));return$x;
}
function items(array $d):array{$out=[];$sources=[['properties','合約／自有'],['sameStoreItems','同店'],['borrowItems','異店／開發'],['peerDevelopmentItems','合作物件']];foreach($sources as [$key,$source])foreach(arrDb($d,$key) as $x){if(!is_array($x)||(!empty($x['hidden'])||($x['saleStatus']??'')==='sold'))continue;$id=firstTxt($x,['id','contractNo','publicNo','sourcePublicNo']);if($id==='')continue;$city=firstTxt($x,['city','county']);$district=firstTxt($x,['district','area','town']);$title=firstTxt($x,['title','objectName','name','caseName']);$main=firstTxt($x,['mainBuildArea','sameStoreMainBuildArea','buildingArea','buildingPing','buildArea','build']);$land=firstTxt($x,['landArea','sameStoreLandArea','landPing']);$total=firstTxt($x,['totalArea','totalPing','totalAreaQuick']);$price=firstTxt($x,['price','sameStorePrice','borrowPrice','totalPrice','salePrice','askingPrice']);$unit=firstTxt($x,['unitPrice','sameStoreUnitPrice']);if($unit===''&&numVal($price)>0){$base=numVal($main)!==0?numVal($main):(numVal($total)!==0?numVal($total):numVal($land));if($base>0)$unit=rtrim(rtrim(number_format(numVal($price)/$base,2,'.',''),'0'),'.').'萬/坪';}$areaParts=[];if($main!=='')$areaParts[]='建 '.$main.'坪';if($land!=='')$areaParts[]='地 '.$land.'坪';if(!$areaParts&&$total!=='')$areaParts[]='總 '.$total.'坪';$missing=[];if($title==='')$missing[]='案名';if($city==='')$missing[]='縣市';if($district==='')$missing[]='鄉鎮區';if(!$areaParts)$missing[]='坪數';if($price==='')$missing[]='總價';$out[$id]=['id'=>$id,'title'=>$title,'city'=>$city,'district'=>$district,'sourceCategory'=>$source,'postMode'=>txt($x['postMode']??''),'mainBuildArea'=>$main,'landArea'=>$land,'totalArea'=>$total,'areaText'=>implode(' / ',$areaParts),'price'=>$price,'unitPrice'=>$unit,'layout'=>firstTxt($x,['layout','sameStoreLayout','roomLayout']),'type'=>firstTxt($x,['type','kind','category','propertyType']),'kind'=>firstTxt($x,['kind','type','category','propertyType']),'floor'=>firstTxt($x,['floor']),'houseAge'=>firstTxt($x,['houseAge']),'summaryZh'=>txt($x['summaryZh']??$x['publicNote']??''),'adText'=>txt($x['adText']??''),'sourceUrl'=>firstTxt($x,['sourceUrl','url','listingUrl']),'imageUrls'=>imageUrls($x),'missingFields'=>$missing];}return array_values($out);}
