$seed=json_decode(@file_get_contents(__DIR__.'/../data/facebook-group-registry-seed.json')?:'[]',true);if(is_array($seed)&&$seed){$groups=arrDb($d,$groupKey);$known=[];foreach($groups as $row)$known[sid($row['id']??'')]=true;$changed=false;foreach($seed as $row){$id=sid($row['id']??'');if($id!==''&&!isset($known[$id])){$groups[]=$row;$known[$id]=true;$changed=true;}}if($changed){$d[$groupKey]=json_encode($groups,JSON_UNESCAPED_UNICODE);writeDb($d);}}
